function renderAnswer(text) {
  const parts = text.split(/(\[DOC-\d\])/g);
  return parts.map((p, i) => {
    const m = p.match(/^\[DOC-(\d)\]$/);
    if (m) {
      return (
        <span
          key={i}
          style={{
            color: TOKENS.teal,
            border: `1px solid ${TOKENS.tealDim}`,
            borderRadius: 4,
            padding: "0 5px",
            fontSize: "11.5px",
            fontFamily: "'IBM Plex Mono', monospace",
            marginLeft: 2,
            whiteSpace: "nowrap",
          }}
        >
          {p}
        </span>
      );
    }
    return <span key={i}>{p}</span>;
  });
}


